/**
 * Reads a comma-separated list of API keys from an environment variable.
 */
function getApiKeys(envVar: string): string[] {
  return (process.env[envVar] ?? '')
    .split(',')
    .map((key) => key.trim())
    .filter(Boolean)
}

/**
 * Extracts the token from an `Authorization: Bearer <token>` header.
 *
 * Returns `null` when the header is missing or not a well-formed Bearer header.
 */
function extractBearerToken(header: string | null): string | null {
  if (!header) return null
  const match = header.match(/^Bearer\s+(.+)$/i)
  return match ? match[1].trim() : null
}

/**
 * Interprets the payload returned by the revalidation-history RPC as a boolean
 * signalling whether a revalidation happened inside the rate-limit window.
 *
 * The RPC returns the recent revalidation history, so any row means there was a
 * recent revalidation.
 */
function wasRecentlyRevalidated(data: unknown): boolean {
  if (data == null) return false
  if (Array.isArray(data)) return data.length > 0
  if (typeof data === 'boolean') return data
  if (typeof data === 'number') return data > 0
  return true
}

function createSupabaseClient() {
  return createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL as string,
    process.env.SUPABASE_SECRET_KEY as string
  )
