 * - Override-tier keys (`DOCS_REVALIDATION_OVERRIDE_KEYS`) bypass the rate
 *   limit entirely.
 */
export async function _handleRevalidateRequest(request: Request): Promise<Response> {
  const authHeader = request.headers.get('authorization')
  if (!authHeader) {
    return new Response('Missing Authorization header', { status: 401 })
  }

  const token = extractBearerToken(authHeader)
  const basicKeys = getApiKeys('DOCS_REVALIDATION_KEYS')
  const overrideKeys = getApiKeys('DOCS_REVALIDATION_OVERRIDE_KEYS')

  const isOverride = token !== null && overrideKeys.includes(token)
  const isBasic = token !== null && basicKeys.includes(token)

  if (!isOverride && !isBasic) {
    return new Response('Invalid Authorization header', { status: 401 })
  }

